import SwiftUI

// Plasmie's geometry, renderer-agnostic. The anchors come from PlasmieShapes (generated by
// app/brand/gen_shapes.py): 12 points on a 100x100 canvas, y down, clockwise from 12
// o'clock. A closed Catmull-Rom spline through them is the body; blending two states'
// anchors is the morph. Face marks are plain paths so the live view (ink on body) and
// the menu-bar glyph (knocked out of a template silhouette) share one drawing.

// MARK: - the 14 states (11 pipeline + 3 mouse reactions)

enum PlasmieState: String, CaseIterable {
    case idle, ingest, summarize, promote, ask, held, error, busy, quiet, off, success
    // transient reactions to the mouse; never derived from the pipeline
    case hi, annoyed, petted

    var anchors: [CGPoint] { PlasmieShapes.anchors[rawValue] ?? PlasmieShapes.anchors["idle"] ?? [] }

    var label: String {
        switch self {
        case .idle:      return "Plasmie is resting. Everything is flowing"
        case .ingest:    return "Plasmie is catching new activity"
        case .summarize: return "Plasmie is summarising your day"
        case .promote:   return "Plasmie is filing new notes"
        case .ask:       return "Plasmie is looking into your question"
        case .held:      return "Plasmie is holding items for your review"
        case .error:     return "Plasmie hit a problem and needs attention"
        case .busy:      return "Plasmie is waiting while the Mac is busy"
        case .quiet:     return "Plasmie is quiet. Nothing new for a while"
        case .off:       return "Plasmie is switched off"
        case .success:   return "Plasmie finished successfully"
        case .hi:        return "Plasmie waves hi"
        case .annoyed:   return "Plasmie is annoyed"
        case .petted:    return "Plasmie is enjoying the pets"
        }
    }

    /// States whose menu-bar glyph keeps moving while they last.
    var animatesMenuBar: Bool {
        switch self {
        case .ingest, .summarize, .promote, .ask, .busy: return true
        default: return false
        }
    }
}

// MARK: - animatable vector

/// An animatable bag of CGFloats. Missing trailing elements read as 0, so two vectors of
/// different length still blend. SwiftUI interpolates this natively between two values.
struct PlasmieVector: VectorArithmetic {
    var v: [CGFloat]
    static let zero = PlasmieVector(v: [])

    init(v: [CGFloat]) { self.v = v }
    init(points: [CGPoint]) { v = points.flatMap { [$0.x, $0.y] } }

    var points: [CGPoint] {
        stride(from: 0, to: v.count - 1, by: 2).map { CGPoint(x: v[$0], y: v[$0 + 1]) }
    }

    private static func zipped(_ a: PlasmieVector, _ b: PlasmieVector, _ f: (CGFloat, CGFloat) -> CGFloat) -> PlasmieVector {
        let n = max(a.v.count, b.v.count)
        return PlasmieVector(v: (0..<n).map { f($0 < a.v.count ? a.v[$0] : 0, $0 < b.v.count ? b.v[$0] : 0) })
    }
    static func + (a: PlasmieVector, b: PlasmieVector) -> PlasmieVector { zipped(a, b, +) }
    static func - (a: PlasmieVector, b: PlasmieVector) -> PlasmieVector { zipped(a, b, -) }
    mutating func scale(by rhs: Double) { v = v.map { $0 * CGFloat(rhs) } }
    var magnitudeSquared: Double { v.reduce(0) { $0 + Double($1 * $1) } }
}

// MARK: - spline + shape

enum PlasmieSpline {
    /// Closed Catmull-Rom through `p`: segment p1->p2 uses c1 = p1 + (p2-p0)/6, c2 = p2 - (p3-p1)/6.
    static func path(_ p: [CGPoint]) -> Path {
        let n = p.count
        guard n >= 3 else { return Path() }
        var path = Path()
        path.move(to: p[0])
        for i in 0..<n {
            let p0 = p[(i + n - 1) % n], p1 = p[i], p2 = p[(i + 1) % n], p3 = p[(i + 2) % n]
            path.addCurve(to: p2,
                          control1: CGPoint(x: p1.x + (p2.x - p0.x) / 6, y: p1.y + (p2.y - p0.y) / 6),
                          control2: CGPoint(x: p2.x - (p3.x - p1.x) / 6, y: p2.y - (p3.y - p1.y) / 6))
        }
        path.closeSubpath()
        return path
    }

    static func lerp(_ a: [CGPoint], _ b: [CGPoint], _ t: CGFloat) -> [CGPoint] {
        zip(a, b).map { CGPoint(x: $0.x + ($1.x - $0.x) * t, y: $0.y + ($1.y - $0.y) * t) }
    }

    static func bounds(_ p: [CGPoint]) -> CGRect {
        guard let f = p.first else { return .zero }
        var r = CGRect(origin: f, size: .zero)
        for q in p { r = r.union(CGRect(origin: q, size: .zero)) }
        return r
    }
}

/// Plasmie's body. `animatableData` is the 24 anchor coordinates, so
/// `withAnimation { shape = other }` morphs between states with no extra code.
struct PlasmieShape: Shape {
    var vec: PlasmieVector
    init(state: PlasmieState) { vec = PlasmieVector(points: state.anchors) }
    init(vec: PlasmieVector) { self.vec = vec }
    var animatableData: PlasmieVector {
        get { vec }
        set { vec = newValue }
    }
    func path(in rect: CGRect) -> Path {
        let sx = rect.width / 100, sy = rect.height / 100
        // Count-agnostic: N anchors = vec.v.count / 2 (any odd trailing element is ignored).
        let pts = vec.points.map { CGPoint(x: rect.minX + $0.x * sx, y: rect.minY + $0.y * sy) }
        return PlasmieSpline.path(pts)
    }
}

// MARK: - face table (mirrors FACES in app/brand/gen_shapes.py)

enum PlasmieEyes { case dot, happy, wink, up, worried, flat, closed, angry }
enum PlasmieMouth { case smile, o, flat, small, wobble, grin, pout, none }
enum PlasmieProp { case dots, card, spark, bang, sweat, sand, zzz, sparkles, hello, vein, hearts }

/// Where the face sits, relative to the body's bounding box so it stays on the body in
/// every shape. Blended across a morph.
struct PlasmieLayout {
    var cx: CGFloat = 0.5      // eye-line centre, fraction of bbox width
    var cy: CGFloat = 0.46     // eye line, fraction of bbox height
    var gap: CGFloat = 0.17    // half eye distance, fraction of bbox width
    var mouthDy: CGFloat = 8   // mouth below the eye line, canvas units
    var scale: CGFloat = 1

    static func mix(_ a: PlasmieLayout, _ b: PlasmieLayout, _ t: CGFloat) -> PlasmieLayout {
        func l(_ x: CGFloat, _ y: CGFloat) -> CGFloat { x + (y - x) * t }
        return PlasmieLayout(cx: l(a.cx, b.cx), cy: l(a.cy, b.cy), gap: l(a.gap, b.gap),
                           mouthDy: l(a.mouthDy, b.mouthDy), scale: l(a.scale, b.scale))
    }
}

struct PlasmieFace {
    let eyes: PlasmieEyes
    let mouth: PlasmieMouth
    let prop: PlasmieProp?
    var blush = false
    var blushScale: CGFloat = 1
    var layout = PlasmieLayout()
}

extension PlasmieState {
    var face: PlasmieFace {
        switch self {
        case .idle:      return PlasmieFace(eyes: .dot, mouth: .smile, prop: nil, blush: true)
        case .ingest:    return PlasmieFace(eyes: .dot, mouth: .o, prop: .dots, layout: PlasmieLayout(cy: 0.55, gap: 0.165, mouthDy: 9))
        case .summarize: return PlasmieFace(eyes: .happy, mouth: .flat, prop: nil, layout: PlasmieLayout(cy: 0.5, gap: 0.17, mouthDy: 8))
        case .promote:   return PlasmieFace(eyes: .wink, mouth: .smile, prop: .card)
        case .ask:       return PlasmieFace(eyes: .up, mouth: .small, prop: .spark, layout: PlasmieLayout(cy: 0.37, gap: 0.17, mouthDy: 9))
        case .held:      return PlasmieFace(eyes: .dot, mouth: .o, prop: .bang, blush: true, layout: PlasmieLayout(cx: 0.48, cy: 0.56, gap: 0.15, mouthDy: 8.5))
        case .error:     return PlasmieFace(eyes: .worried, mouth: .wobble, prop: .sweat, layout: PlasmieLayout(cy: 0.42, gap: 0.17, mouthDy: 8))
        case .busy:      return PlasmieFace(eyes: .flat, mouth: .flat, prop: .sand, layout: PlasmieLayout(cy: 0.17, gap: 0.17, mouthDy: 5.5, scale: 0.85))
        case .quiet:     return PlasmieFace(eyes: .closed, mouth: .none, prop: .zzz, layout: PlasmieLayout(cy: 0.42, gap: 0.14))
        case .off:       return PlasmieFace(eyes: .closed, mouth: .none, prop: nil, layout: PlasmieLayout(cy: 0.5, gap: 0.15, scale: 0.9))
        case .success:   return PlasmieFace(eyes: .happy, mouth: .grin, prop: .sparkles, blush: true, layout: PlasmieLayout(cy: 0.5, gap: 0.15, mouthDy: 8.5))
        case .hi:        return PlasmieFace(eyes: .happy, mouth: .grin, prop: .hello, blush: true, layout: PlasmieLayout(cy: 0.5, gap: 0.15, mouthDy: 8.5))
        case .annoyed:   return PlasmieFace(eyes: .angry, mouth: .pout, prop: .vein, layout: PlasmieLayout(cy: 0.5, gap: 0.17, mouthDy: 10))
        case .petted:    return PlasmieFace(eyes: .happy, mouth: .smile, prop: .hearts, blush: true, blushScale: 1.35, layout: PlasmieLayout(cy: 0.42, gap: 0.17, mouthDy: 8.5))
        }
    }
}

// MARK: - face parameters (what animates)

/// Everything the face is made of, as plain numbers, so an expression change is an
/// interpolation instead of a crossfade. Eyes: openness 0...1 (a dot's height), curve
/// -1...1 (happy arc up, closed arc down), brow tilt (-1 worried ... +1 angry). Mouth:
/// width, curve (end drop and belly depth), openness (stroke -> filled), wobble.
struct PlasmieFaceParams {
    // layout
    var cx: CGFloat = 0.5, cy: CGFloat = 0.46, gap: CGFloat = 0.17, mouthDy: CGFloat = 8, scale: CGFloat = 1
    // eyes
    var eyeLOpen: CGFloat = 1, eyeLCurve: CGFloat = 0, eyeROpen: CGFloat = 1, eyeRCurve: CGFloat = 0
    var look: CGFloat = 0, browTilt: CGFloat = 0, browAlpha: CGFloat = 0
    // mouth: half width, end drop, upper/lower edge control offsets, control spread, filled, wobble, visible
    var mHW: CGFloat = 4.6, mEnd: CGFloat = 0, mUp: CGFloat = 0, mLow: CGFloat = 3.6, mKx: CGFloat = 1.0 / 3
    var mFill: CGFloat = 0, mWob: CGFloat = 0, mVis: CGFloat = 1
    // blush
    var blush: CGFloat = 0, blushScale: CGFloat = 1
    var dim: CGFloat = 0          // 1 = switched off (grey body)

    static let count = 23

    var array: [CGFloat] {
        [cx, cy, gap, mouthDy, scale, eyeLOpen, eyeLCurve, eyeROpen, eyeRCurve, look, browTilt, browAlpha,
         mHW, mEnd, mUp, mLow, mKx, mFill, mWob, mVis, blush, blushScale, dim]
    }

    init(array a: [CGFloat]) {
        var v = a
        while v.count < Self.count { v.append(0) }
        (cx, cy, gap, mouthDy, scale, eyeLOpen, eyeLCurve, eyeROpen, eyeRCurve, look, browTilt, browAlpha) =
            (v[0], v[1], v[2], v[3], v[4], v[5], v[6], v[7], v[8], v[9], v[10], v[11])
        (mHW, mEnd, mUp, mLow, mKx, mFill, mWob, mVis, blush, blushScale, dim) =
            (v[12], v[13], v[14], v[15], v[16], v[17], v[18], v[19], v[20], v[21], v[22])
    }

    init(_ face: PlasmieFace, layout: PlasmieLayout? = nil) {
        let l = layout ?? face.layout
        (cx, cy, gap, mouthDy, scale) = (l.cx, l.cy, l.gap, l.mouthDy, l.scale)
        switch face.eyes {
        case .dot:     break
        case .happy:   (eyeLOpen, eyeLCurve, eyeROpen, eyeRCurve) = (0, 1, 0, 1)
        case .wink:    (eyeROpen, eyeRCurve) = (0, 1)
        case .up:      look = -2.6
        case .worried: (browTilt, browAlpha) = (-1, 1)
        case .flat:    (eyeLOpen, eyeROpen) = (0, 0)
        case .closed:  (eyeLOpen, eyeLCurve, eyeROpen, eyeRCurve) = (0, -1, 0, -1)
        case .angry:   (browTilt, browAlpha) = (1, 1)
        }
        switch face.mouth {
        case .smile:  break
        case .small:  (mHW, mLow) = (2.8, 2)
        case .flat:   (mHW, mLow) = (3.6, 0)
        case .pout:   (mHW, mEnd, mLow) = (3.6, 1.6, -2.93)
        case .o:      (mHW, mUp, mLow, mKx, mFill) = (2.9, -4.67, 4.67, 1.333, 1)
        case .wobble: (mHW, mLow, mWob) = (5.5, 0, 1)
        case .grin:   (mHW, mEnd, mLow, mFill) = (5.6, -1.4, 8.93, 1)
        case .none:   (mHW, mLow, mVis) = (3.6, 0, 0)
        }
        blush = face.blush ? 1 : 0
        blushScale = face.blushScale
    }
}

// MARK: - body pose = polar anchors + face

/// One animatable vector: [cx, cy, (angle, radius) x N, face params]. The body morphs in
/// POLAR form about its centroid, so a star and an hourglass swap by growing and shrinking
/// along rays instead of cutting through themselves the way a straight-line blend can.
enum PlasmiePose {
    private static func wrap(_ x: Double) -> Double { x - 2 * .pi * (x / (2 * .pi)).rounded() }

    static func polar(_ pts: [CGPoint]) -> [CGFloat] {
        guard !pts.isEmpty else { return [] }
        let cx = pts.reduce(0) { $0 + $1.x } / CGFloat(pts.count)
        let cy = pts.reduce(0) { $0 + $1.y } / CGFloat(pts.count)
        var out: [CGFloat] = [cx, cy]
        var prev = 0.0
        for (i, p) in pts.enumerated() {
            let raw = atan2(Double(p.y - cy), Double(p.x - cx))
            let a = i == 0 ? -.pi / 2 + wrap(raw + .pi / 2) : prev + wrap(raw - prev)   // unwrapped, clockwise
            prev = a
            out += [CGFloat(a), hypot(p.x - cx, p.y - cy)]
        }
        return out
    }

    /// Total angular sweep of a state's anchors; 2 pi for every well-formed (star-shaped) body.
    static func sweep(_ s: PlasmieState) -> Double {
        let v = polar(s.anchors)
        guard v.count >= 6 else { return 0 }
        return Double(v[v.count - 2] - v[2])
    }

    private static let table: [PlasmieState: PlasmieVector] = Dictionary(
        uniqueKeysWithValues: PlasmieState.allCases.map { st -> (PlasmieState, PlasmieVector) in
            var f = PlasmieFaceParams(st.face)
            f.dim = st == .off ? 1 : 0
            return (st, PlasmieVector(v: polar(st.anchors) + f.array))
        })

    static func vector(_ s: PlasmieState) -> PlasmieVector { table[s] ?? .zero }

    static func decode(_ vec: PlasmieVector) -> (points: [CGPoint], face: PlasmieFaceParams) {
        let v = vec.v
        let n = (v.count - 2 - PlasmieFaceParams.count) / 2
        guard n >= 3 else { return ([], PlasmieFaceParams(array: [])) }
        let pts = (0..<n).map { i -> CGPoint in
            let a = Double(v[2 + 2 * i]), r = max(v[3 + 2 * i], 0)
            return CGPoint(x: v[0] + r * CGFloat(cos(a)), y: v[1] + r * CGFloat(sin(a)))
        }
        return (pts, PlasmieFaceParams(array: Array(v[(2 + 2 * n)...])))
    }
}

// MARK: - face marks

struct PlasmieMark {
    enum Tone { case ink, blush }
    var path: Path
    var stroke: CGFloat?     // nil = filled
    var tone: Tone
    var alpha: Double = 1
}

enum PlasmieFaceArt {
    /// Marks for a settled face (menu-bar glyph, proofs).
    static func marks(_ face: PlasmieFace, layout: PlasmieLayout, box: CGRect,
                      eye: CGFloat = 1, line: CGFloat = 1) -> [PlasmieMark] {
        marks(PlasmieFaceParams(face, layout: layout), box: box, eye: eye, line: line)
    }

    /// Eyes, mouth and blush for `p`, positioned inside `box` (canvas units).
    /// `eye`/`line` scale dot size and stroke weight (the 18pt glyph needs bolder marks);
    /// `blink` (0...1) closes dot eyes.
    static func marks(_ p: PlasmieFaceParams, box: CGRect, eye: CGFloat = 1, line: CGFloat = 1,
                      blink: CGFloat = 0) -> [PlasmieMark] {
        let s = p.scale
        let ex = box.minX + p.cx * box.width
        let ey = box.minY + p.cy * box.height
        let gap = p.gap * box.width
        let my = ey + p.mouthDy * s
        let w = 2.3 * s * line
        var out: [PlasmieMark] = []

        func eyeMarks(_ x: CGFloat, open: CGFloat, curve: CGFloat) {
            let c = CGPoint(x: x, y: ey + p.look * s)
            let o = max(open, 0) * (1 - blink)
            if o > 0.03 {
                let rx = 3.0 * s * eye
                out.append(PlasmieMark(path: Path(ellipseIn: CGRect(x: c.x - rx, y: c.y - rx * min(o, 1.2), width: 2 * rx, height: 2 * rx * min(o, 1.2))),
                                     stroke: nil, tone: .ink))
            }
            let a = Double(min(max(1 - o, 0), 1))
            guard a > 0.02 else { return }
            let hw = (3.2 + 0.4 * abs(curve)) * s
            let endY = (curve >= 0 ? 1.6 * curve : curve) * s
            let ctlY = -curve * (curve >= 0 ? 4.6 : 4.2) * s
            var path = Path()
            path.move(to: CGPoint(x: c.x - hw, y: c.y + endY))
            path.addQuadCurve(to: CGPoint(x: c.x + hw, y: c.y + endY), control: CGPoint(x: c.x, y: c.y + ctlY))
            out.append(PlasmieMark(path: path, stroke: w * (1.05 - 0.05 * min(abs(curve), 1)), tone: .ink, alpha: a))
        }
        eyeMarks(ex - gap, open: p.eyeLOpen, curve: p.eyeLCurve)
        eyeMarks(ex + gap, open: p.eyeROpen, curve: p.eyeRCurve)

        // brows are fine detail: skipped on the 18pt glyph (line > 1), where they read as noise
        if p.browAlpha > 0.02 && line <= 1.01 {
            let outer = -6.9 - 1.85 * p.browTilt, inner = -6.9 + 1.85 * p.browTilt
            for sign: CGFloat in [-1, 1] {
                let x = ex + sign * gap
                var path = Path()
                path.move(to: CGPoint(x: x - sign * 3.7 * s, y: ey + outer * s))
                path.addLine(to: CGPoint(x: x + sign * 3.3 * s, y: ey + inner * s))
                out.append(PlasmieMark(path: path, stroke: 1.9 * s * line, tone: .ink, alpha: Double(p.browAlpha)))
            }
        }

        // mouth: one parametric shape. Stroked lower edge, filled lens, or the wobble line.
        let vis = Double(p.mVis)
        if vis > 0.02 {
            let kxBlend = min(max((p.mKx - 1.0 / 3) / 1.0, 0), 1)
            let k = 1 + (eye - 1) * kxBlend                       // only the round "o" grows with `eye`
            let hw = p.mHW * s * k, kx = p.mKx
            let ya = my + p.mEnd * s
            let a = CGPoint(x: ex - hw, y: ya), b = CGPoint(x: ex + hw, y: ya)
            let lowY = ya + p.mLow * s * k, upY = ya + p.mUp * s * k
            let strokeA = Double((1 - min(max(p.mFill, 0), 1)) * (1 - min(max(p.mWob, 0), 1))) * vis
            if strokeA > 0.02 {
                var path = Path()
                path.move(to: a)
                path.addCurve(to: b, control1: CGPoint(x: ex - hw * kx, y: lowY), control2: CGPoint(x: ex + hw * kx, y: lowY))
                out.append(PlasmieMark(path: path, stroke: w, tone: .ink, alpha: strokeA))
            }
            let fillA = Double(min(max(p.mFill, 0), 1)) * vis
            if fillA > 0.02 {
                var path = Path()
                path.move(to: a)
                path.addCurve(to: b, control1: CGPoint(x: ex - hw * kx, y: upY), control2: CGPoint(x: ex + hw * kx, y: upY))
                path.addCurve(to: a, control1: CGPoint(x: ex + hw * kx, y: lowY), control2: CGPoint(x: ex - hw * kx, y: lowY))
                path.closeSubpath()
                out.append(PlasmieMark(path: path, stroke: nil, tone: .ink, alpha: fillA))
            }
            let wobA = Double(min(max(p.mWob, 0), 1)) * vis
            if wobA > 0.02 {
                var path = Path()
                path.move(to: CGPoint(x: ex - 5.5 * s, y: my))
                path.addCurve(to: CGPoint(x: ex, y: my),
                              control1: CGPoint(x: ex - 4 * s, y: my - 3 * s), control2: CGPoint(x: ex - 1.6 * s, y: my + 3 * s))
                path.addCurve(to: CGPoint(x: ex + 5.5 * s, y: my),
                              control1: CGPoint(x: ex + 1.6 * s, y: my - 3 * s), control2: CGPoint(x: ex + 4 * s, y: my + 3 * s))
                out.append(PlasmieMark(path: path, stroke: w, tone: .ink, alpha: wobA))
            }
        }

        if p.blush > 0.02 {
            let bs = p.blushScale
            for sign: CGFloat in [-1, 1] {
                let c = CGPoint(x: ex + sign * (gap + 5.4 * s), y: ey + 5.6 * s)
                out.append(PlasmieMark(path: Path(ellipseIn: CGRect(x: c.x - 4.2 * s * bs, y: c.y - 2.6 * s * bs, width: 8.4 * s * bs, height: 5.2 * s * bs)),
                                     stroke: nil, tone: .blush, alpha: Double(p.blush)))
            }
        }
        return out
    }
}


// MARK: - evolution accessories

/// Stage accessories, drawn on Plasmie's 100x100 canvas relative to the current shape's
/// bounding box (mirrors drawAccessory in app/brand/plasmie-brand.template.html).
enum PlasmieAccessoryArt {
    static func draw(_ acc: String, box b: CGRect, in c: GraphicsContext, scheme: ColorScheme) {
        let cx = b.midX, top = b.minY
        let ink = PlasmieHues.ink.color(scheme)
        let spark = PlasmieHues.sparkle.color(scheme)
        let stroke = StrokeStyle(lineWidth: 1.8, lineCap: .round, lineJoin: .round)
        func pt(_ x: CGFloat, _ y: CGFloat) -> CGPoint { CGPoint(x: x, y: y) }
        func fillStroke(_ p: Path, _ fill: Color, lineWidth: CGFloat = 1.8) {
            c.fill(p, with: .color(fill))
            c.stroke(p, with: .color(ink), style: StrokeStyle(lineWidth: lineWidth, lineCap: .round, lineJoin: .round))
        }
        func ellipse(_ x: CGFloat, _ y: CGFloat, _ rx: CGFloat, _ ry: CGFloat, deg: Double = 0) -> Path {
            let e = Path(ellipseIn: CGRect(x: -rx, y: -ry, width: 2 * rx, height: 2 * ry))
            return e.applying(CGAffineTransform(rotationAngle: CGFloat(deg * .pi / 180)).concatenating(CGAffineTransform(translationX: x, y: y)))
        }

        switch acc {
        case "eggshell":
            var p = Path()
            p.move(to: pt(cx - 17, top + 7))
            p.addQuadCurve(to: pt(cx, top - 13), control: pt(cx - 15, top - 12))
            p.addQuadCurve(to: pt(cx + 17, top + 7), control: pt(cx + 15, top - 12))
            for q in [(12, 2), (7, 8), (2, 2), (-3, 8), (-8, 2), (-13, 8)] { p.addLine(to: pt(cx + CGFloat(q.0), top + CGFloat(q.1))) }
            p.closeSubpath()
            fillStroke(p, PlasmieHues.eggshell.color(scheme))
        case "leaf":
            var stem = Path()
            stem.move(to: pt(cx, top + 3))
            stem.addQuadCurve(to: pt(cx + 2, top - 11), control: pt(cx - 1, top - 6))
            c.stroke(stem, with: .color(ink), style: stroke)
            fillStroke(ellipse(cx - 5, top - 12, 7, 3.6, deg: -28), PlasmieHues.leaf.color(scheme))
            fillStroke(ellipse(cx + 8, top - 14, 7, 3.6, deg: 24), PlasmieHues.leaf.color(scheme))
        case "glasses":
            let ey = b.minY + min(b.height * 0.42, b.height - 14), gap = min(b.width * 0.17, 13)
            for s in [-1.0, 1.0] {
                let r = Path(ellipseIn: CGRect(x: cx + CGFloat(s) * gap - 7.6, y: ey - 7.6, width: 15.2, height: 15.2))
                c.fill(r, with: .color(.white.opacity(0.22)))
                c.stroke(r, with: .color(ink), style: StrokeStyle(lineWidth: 2, lineCap: .round, lineJoin: .round))
            }
            var bridge = Path()
            bridge.move(to: pt(cx - gap + 7.6, ey))
            bridge.addQuadCurve(to: pt(cx + gap - 7.6, ey), control: pt(cx, ey - 3))
            c.stroke(bridge, with: .color(ink), style: stroke)
        case "mortarboard":
            var band = Path()
            band.move(to: pt(cx - 12, top - 3)); band.addLine(to: pt(cx - 12, top + 5))
            band.addQuadCurve(to: pt(cx + 12, top + 5), control: pt(cx, top + 9))
            band.addLine(to: pt(cx + 12, top - 3)); band.closeSubpath()
            fillStroke(band, ink)
            var board = Path()
            board.move(to: pt(cx - 25, top - 6)); board.addLine(to: pt(cx, top - 15))
            board.addLine(to: pt(cx + 25, top - 6)); board.addLine(to: pt(cx, top + 3)); board.closeSubpath()
            fillStroke(board, ink)
            var tassel = Path()
            tassel.move(to: pt(cx, top - 6))
            tassel.addQuadCurve(to: pt(cx + 19, top + 1), control: pt(cx + 14, top - 4))
            tassel.addLine(to: pt(cx + 19, top + 11))
            c.stroke(tassel, with: .color(spark), style: stroke)
            c.fill(Path(ellipseIn: CGRect(x: cx + 19 - 2.4, y: top + 12 - 2.4, width: 4.8, height: 4.8)), with: .color(spark))
        case "wizard-hat":
            var cone = Path()
            cone.move(to: pt(cx - 18, top + 3))
            cone.addQuadCurve(to: pt(cx + 9, top - 34), control: pt(cx - 4, top - 18))
            cone.addQuadCurve(to: pt(cx + 18, top + 3), control: pt(cx + 6, top - 16))
            cone.closeSubpath()
            fillStroke(cone, ink)
            fillStroke(ellipse(cx, top + 3, 24, 4.5), ink)
            for (x, y, r) in [(cx - 4, top - 8, 2.6), (cx + 5, top - 18, 2.0), (cx + 3, top - 3, 1.6)] {
                var st = Path()
                let k = r * 0.35
                st.move(to: pt(x, y - r)); st.addLine(to: pt(x + k, y - k)); st.addLine(to: pt(x + r, y))
                st.addLine(to: pt(x + k, y + k)); st.addLine(to: pt(x, y + r)); st.addLine(to: pt(x - k, y + k))
                st.addLine(to: pt(x - r, y)); st.addLine(to: pt(x - k, y - k)); st.closeSubpath()
                c.fill(st, with: .color(spark))
            }
        case "crown":
            var p = Path()
            p.move(to: pt(cx - 17, top + 3)); p.addLine(to: pt(cx - 18, top - 11)); p.addLine(to: pt(cx - 9, top - 3))
            p.addLine(to: pt(cx, top - 15)); p.addLine(to: pt(cx + 9, top - 3)); p.addLine(to: pt(cx + 18, top - 11))
            p.addLine(to: pt(cx + 17, top + 3)); p.closeSubpath()
            fillStroke(p, spark)
            for x in [cx - 9, cx, cx + 9] {
                c.fill(Path(ellipseIn: CGRect(x: x - 1.8, y: top - 1 - 1.8, width: 3.6, height: 3.6)), with: .color(PlasmieHues.blush.color(scheme)))
            }
        default: break
        }
    }
}
